import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { buildBriefing } from "./briefing.js";

describe("buildBriefing", () => {
  let mgmtDir: string;
  const featureId = "test-feature";
  const taskId = "T3";

  beforeEach(() => {
    mgmtDir = join(tmpdir(), `briefing-test-${Date.now()}`);
    const tasksDir = join(mgmtDir, "docs", "features", featureId, "tasks");
    mkdirSync(tasksDir, { recursive: true });

    writeFileSync(
      join(tasksDir, `${taskId}.yaml`),
      `id: ${taskId}\ntitle: Test task\nstatus: in_progress\n`,
      "utf-8",
    );

    writeFileSync(
      join(mgmtDir, "docs", "features", featureId, "tasks.md"),
      [
        "## T1 — First task",
        "Description of T1.",
        "---",
        `## ${taskId} — Test task`,
        "Description of T3.",
        "### Subtasks",
        "- [ ] Do the thing",
        "---",
        "## T4 — Another task",
        "Description of T4.",
      ].join("\n"),
      "utf-8",
    );

    writeFileSync(
      join(mgmtDir, "docs", "features", featureId, "technical-design.md"),
      "# Technical Design\n\nThis is the technical design.",
      "utf-8",
    );
  });

  afterEach(() => {
    rmSync(mgmtDir, { recursive: true, force: true });
  });

  it("returns a string containing the task YAML", () => {
    const result = buildBriefing(mgmtDir, {
      workspaceId: "ws-1",
      taskId,
      featureId,
      taskRepoPath: "/some/path",
    });
    expect(result).toContain(`id: ${taskId}`);
    expect(result).toContain("title: Test task");
  });

  it("returns a string containing the tasks.md section for the task", () => {
    const result = buildBriefing(mgmtDir, {
      workspaceId: "ws-1",
      taskId,
      featureId,
      taskRepoPath: "/some/path",
    });
    expect(result).toContain("Description of T3.");
    expect(result).toContain("Do the thing");
    // Should not include the next task's section
    expect(result).not.toContain("Description of T4.");
  });

  it("returns a string containing the technical design", () => {
    const result = buildBriefing(mgmtDir, {
      workspaceId: "ws-1",
      taskId,
      featureId,
      taskRepoPath: "/some/path",
    });
    expect(result).toContain("This is the technical design.");
  });

  it("includes workspaceId and taskRepoPath", () => {
    const result = buildBriefing(mgmtDir, {
      workspaceId: "my-workspace",
      taskId,
      featureId,
      taskRepoPath: "/workspace/impl",
    });
    expect(result).toContain("my-workspace");
    expect(result).toContain("/workspace/impl");
  });

